            "syntax": "class Student:\n    school_name = \"EduAdapt Academy\"  # Class attribute\n    \n    def __init__(self, name, student_id):\n        self.name = name              # Instance attribute\n        self.student_id = student_id\n    \n    def get_info(self):\n        return f\"{self.name} ({self.student_id})\"\n",
