            "syntax": "public class Course {\n    private String name;\n    private int hours;\n    \n    public Course(String name) {\n        this(name, 40); // Chains to two-arg constructor\n    }\n    \n    public Course(String name, int hours) {\n        this.name = name;\n        this.hours = hours;\n    }\n}\n",
